def _candidate_pipeline_runtime(deps: QuarterNotesUiCandidatePipelineDeps) -> Dict[str, Any]:
    env: Dict[str, Any] = dict(deps.runtime)
    audit_trace = deps.audit_trace
    env.update(
        {
            "Any": Any,
            "Callable": Callable,
            "Dict": Dict,
            "List": List,
            "Mapping": Mapping,
            "MutableMapping": MutableMapping,
            "Sequence": Sequence,
            "Tuple": Tuple,
            "date": date,
            "hashlib": hashlib,
            "pd": pd,
            "time": time,
            "QuarterNotesUiCandidateSupport": QuarterNotesUiCandidateSupport,
            "QuarterNotesUiCandidateSupportDeps": QuarterNotesUiCandidateSupportDeps,
            "quarter_notes_audit_trace": audit_trace,
            "quarter_notes_audit_rows": audit_trace.raw_rows,
            "_audit_family_hint_local": audit_trace.family_hint,
            "_audit_subject_variant_hint_local": audit_trace.subject_variant_hint,
            "_capital_allocation_confidence_local": audit_trace.capital_allocation_confidence,
            "_clean_audit_excerpt_local": audit_trace.clean_excerpt,
            "_canonicalize_audit_excerpt_local": audit_trace.canonicalize_excerpt,
            "_audit_doc_family_local": audit_trace.doc_family,
            "_quarter_notes_audit_canonical_rows_local": audit_trace.canonical_rows,
            "_quarter_note_trace_id_local": audit_trace.trace_id,
            "_audit_attrition_class_local": audit_trace.attrition_class,
            "_emit_quarter_note_audit_row": audit_trace.emit,
            "_ensure_note_trace_id_local": audit_trace.ensure_trace_id,
            "_audit_register_existing_candidate_local": audit_trace.register_existing,
            "_quarter_notes_candidate_support": deps.candidate_support,
            "_quarter_notes_candidate_support_state": deps.candidate_support_state,
            "ui_info_rows": deps.ui_info_rows,
            "_harvest_fy_expense_driver_rows": deps.harvest_fy_expense_driver_rows,
            "_harvest_interim_expense_driver_rows": deps.harvest_interim_expense_driver_rows,
            "_harvest_mdna_cashflow_driver_rows": deps.harvest_mdna_cashflow_driver_rows,
            "_harvest_debt_pension_action_rows": deps.harvest_debt_pension_action_rows,
        }
    )
    return env


def _exec_candidate_pipeline_code(code: str, env: Dict[str, Any]) -> None:
    wrapper_name = "__quarter_notes_candidate_pipeline_exec__"
    prebound = "\n".join(
        f"    {name} = globals()[{name!r}]" for name in _PREBOUND_RUNTIME_NAMES
    )
    indented = "\n".join(f"    {line}" if line else "" for line in code.splitlines())
    wrapped = f"def {wrapper_name}():\n{prebound}\n{indented}\n    return locals()\n"
    exec(wrapped, env, env)
    local_env = env.pop(wrapper_name)()
    env.update(local_env)


class QuarterNotesUiCandidatePipeline:
    def __init__(self, deps: QuarterNotesUiCandidatePipelineDeps) -> None:
        self.deps = deps

    def build(self) -> QuarterNotesUiCandidatePipelineResult:
        env = _candidate_pipeline_runtime(self.deps)
        _exec_candidate_pipeline_code(_CANDIDATE_PIPELINE_CODE, env)
        best_by_key = env.get("best_by_key")
        if not isinstance(best_by_key, dict):
            best_by_key = {}
        q_stats = env.get("q_stats")
        if not isinstance(q_stats, dict):
            q_stats = {}
        candidate_support = env.get("_quarter_notes_candidate_support") or self.deps.candidate_support
        return QuarterNotesUiCandidatePipelineResult(
            records=list(best_by_key.values()),
            best_by_key=best_by_key,
            q_stats=q_stats,
            ui_info_rows=self.deps.ui_info_rows,
            candidate_support=candidate_support,
        )
